// Commercial workflows: local demonstration, no external messages or shared server.
state.crm ||= {visits:[],expenses:[],threads:[],followups:[],consignments:[],goals:{},stockLog:[],tables:{},locationStock:{},schema:1};
const crm=state.crm;
for(const k of ['visits','expenses','threads','followups','consignments','stockLog'])crm[k] ||= [];
for(const k of ['goals','tables','locationStock'])crm[k] ||= {};
state.managers ||= [state.manager];
for(const o of [...state.orders,...state.samples,...crm.consignments])for(const i of o.items)i.location ||= 'A';
for(const i of state.cart.items)i.location ||= 'A';
for(const c of Object.values(state.carts))for(const i of c.items||[])i.location ||= 'A';
const PLACES={A:'A · Estoque fábrica',B:'B · Galpão estratégico'};
const TABLES=['Oficina','Loja','Distribuidor'];
const APPROVED=['Confirmado','Em preparação','Concluído'];
state.samples.forEach(s=>{if(s.stockApplied===undefined)s.stockApplied=APPROVED.includes(s.status)});
const now=()=>new Date().toISOString();
const today=()=>new Date().toLocaleDateString('sv-SE');
const monthNow=()=>today().slice(0,7);
const digits=x=>String(x||'').replace(/\D/g,'');
const mine=x=>role==='gestor'||x.rep===user;
const clientById=id=>state.clients.find(c=>c.id===id);
const shortDate=s=>s?new Date(s).toLocaleString('pt-BR'):'—';
function crmSave(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Não foi possível salvar. O armazenamento local pode estar cheio. Reduza as fotos e tente novamente.');return false}}
function logStock(kind,items,note=''){crm.stockLog.push({id:uid(),date:now(),by:user||'Migração',kind,note,items:structuredClone(items)});}
function placeKey(id,pack,place){return `${place}::${sku(id,pack)}`}
// Preserve old physical stock in A; B begins empty. Existing records stay in A.
for(const p of PRODUCTS)for(const v of variants(p)){
 const a=placeKey(p.id,v,'A'),b=placeKey(p.id,v,'B');
 if(crm.locationStock[a]===undefined)crm.locationStock[a]=state.inventory[sku(p.id,v)]??100;
 if(crm.locationStock[b]===undefined)crm.locationStock[b]=0;
}
function locationOf(i){return i.location==='B'?'B':'A'}
function stock(id,pack,place){return place?Number(crm.locationStock[placeKey(id,pack,place)]||0):stock(id,pack,'A')+stock(id,pack,'B')}
function reserved(id,pack,place){
 const docs=[...state.orders,...state.samples,...crm.consignments];
 return docs.filter(o=>o.status==='Aguardando aprovação'&&!o.stockExempt).reduce((n,o)=>n+o.items.filter(i=>i.id===id&&itemPack(i)===pack&&(!place||locationOf(i)===place)).reduce((v,i)=>v+i.qty,0),0);
}
function available(id,pack,place){if(!place)return available(id,pack,'A')+available(id,pack,'B');return Math.max(0,stock(id,pack,place)-reserved(id,pack,place))}
function groupedItems(items){const groups={};for(const i of items){const place=locationOf(i),pack=itemPack(i),key=placeKey(i.id,pack,place);groups[key] ||= {id:i.id,pack,location:place,qty:0};groups[key].qty+=i.qty}return Object.values(groups)}
let chosenLocation='A';
function checkItems(items){for(const i of items){i.location ||= chosenLocation;if(!Number.isInteger(i.qty)||i.qty<1){toast('Informe quantidades inteiras positivas.');return false}}
 for(const i of groupedItems(items))if(i.qty>available(i.id,i.pack,i.location)){toast(`Sem estoque disponível em ${PLACES[i.location]}: ${product(i.id)?.name}, ${i.pack}.`);return false}return true;
}
function takeStock(items,ownReservation=false){
 const groups=groupedItems(items);
 for(const i of groups){const other=reserved(i.id,i.pack,i.location)-(ownReservation?i.qty:0);if(stock(i.id,i.pack,i.location)-other<i.qty){toast('Estoque insuficiente no local escolhido. Confira as reservas.');return false}}
 for(const i of groups)crm.locationStock[placeKey(i.id,i.pack,i.location)]-=i.qty;
 logStock('Baixa',groups);return true;
}
function returnStock(items,note=''){for(const i of groupedItems(items))crm.locationStock[placeKey(i.id,i.pack,i.location)]+=i.qty;logStock('Reposição',items,note)}
function consumeStock(items){return takeStock(items,true)}
function approvalDate(o){return o.approvedAt||(o.history||[]).find(h=>APPROVED.includes(h.status))?.date||o.date}
function transitionOrder(o,s,note=''){
 if(role!=='gestor')return false;
 if(['Cancelado','Não aprovado'].includes(s)&&!note.trim()){toast('Informe o motivo.');return false}
 const charged=APPROVED.includes(s),wasCharged=o.stockApplied===true;
 if(o.consignmentId && s!==o.status){toast('Este pedido veio de acerto de consignação. Correções precisam de conferência da gestão; não altere o estoque por aqui.');return false}
 if(charged&&!wasCharged&&!takeStock(o.items,o.status==='Aguardando aprovação'))return false;
 if(!charged&&wasCharged)returnStock(o.items,'Pedido #'+o.number+' → '+s);
 if(s==='Aguardando aprovação'&&o.status!=='Aguardando aprovação'){
  const own=o.status;o.status=s;
  const invalid=groupedItems(o.items).some(i=>reserved(i.id,i.pack,i.location)>stock(i.id,i.pack,i.location));o.status=own;
  if(invalid){if(wasCharged&& !charged)takeStock(o.items,false);toast('Não é possível reabrir: estoque já reservado por outro pedido.');return false}
 }
 o.status=s;o.stockApplied=charged;o.managerNote=note;
 if(charged&&!wasCharged){o.approvedAt=now();if(state.orders.includes(o))queueWhatsApp(o,'approved')}
 if(s==='Cancelado'||s==='Não aprovado')o.reason=note;else delete o.reason;
 o.history ||= [];o.history.push({status:s,date:now(),by:user,note});
 logStock(s==='Aguardando aprovação'?'Reserva':charged?'Pedido aprovado':'Liberação de reserva',o.items,'Pedido #'+o.number);
 return true;
}
function priceTable(c){return c?.establishment==='Outros'?(TABLES.includes(c.priceTable)?c.priceTable:null):(TABLES.includes(c?.establishment)?c.establishment:'Oficina')}
function tableBase(p,pack,table){return crm.tables[`${table}::${sku(p.id,pack)}`]??baseVariantPrice(p,pack)}
function variantPrice(p,pack){const c=clientById(state.cart.client),table=priceTable(c)||'Oficina';return Math.round(tableBase(p,pack,table)*(1-(offerActive(p)?.percent||0)/100)*100)/100}
function repriceCart(){const c=clientById(state.cart.client),table=priceTable(c);if(!table)return;for(const i of state.cart.items){i.price=variantPrice(product(i.id),itemPack(i));i.priceTable=table}}
const oldChooseItem=chooseItem;
chooseItem=function(id,sample=false){
 if(!sample){const c=clientById(state.cart.client);if(!c){toast('Selecione ou cadastre o cliente antes de escolher os produtos.');go('clients');return}if(!priceTable(c)){toast('O gestor precisa definir a tabela de preços deste cliente.');return}}
 chosenLocation=available(id,variants(product(id))[0],'A')>0?'A':'B';
 oldChooseItem(id,sample);const form=$('#item-form');if(!form)return;
 const place=document.createElement('label');place.innerHTML=`Local de saída<select id="pick-location" class="wide">${Object.entries(PLACES).map(([k,v])=>`<option value="${k}" ${chosenLocation===k?'selected':''}>${v}</option>`).join('')}</select>`;
 $('#pick-stock').insertAdjacentElement('afterend',place);
 const sync=()=>{chosenLocation=$('#pick-location').value;const pack=$('#pick-pack').value;$('#pick-stock').textContent=`${PLACES[chosenLocation]}: ${available(id,pack,chosenLocation)} disponível(is) · ${reserved(id,pack,chosenLocation)} reservado(s)`};
 const previous=$('#pick-pack').onchange;$('#pick-pack').onchange=()=>{previous?.();sync()};$('#pick-location').onchange=sync;sync();
 if(!sample)form.insertAdjacentHTML('afterbegin',`<p class="note">Cliente: <strong>${esc(clientById(state.cart.client)?.name)}</strong> · Tabela: ${esc(priceTable(clientById(state.cart.client)))}</p>`);
 const submit=form.onsubmit;form.onsubmit=e=>{const before=state.samples.length;submit(e);if(state.samples.length>before){state.samples.at(-1).stockApplied=false;logStock('Reserva de amostra',state.samples.at(-1).items);crmSave()}};
};
const oldCart=cart;
cart=function(){oldCart();const select=$('#cart-client');if(!select)return;const onChange=select.onchange;select.onchange=e=>{onChange(e);repriceCart();save();cart();toast('Preços atualizados para a tabela do cliente selecionado.')};
 const onSubmit=$('#submit-order').onclick;$('#submit-order').onclick=()=>{const c=clientById(state.cart.client);if(!priceTable(c)){toast('O gestor precisa definir a tabela de preços deste cliente.');return}const n=state.orders.length;onSubmit();if(state.orders.length>n){const o=state.orders.at(-1);o.priceTable=priceTable(c);o.stockApplied=false;logStock('Reserva de pedido',o.items,'Pedido #'+o.number);crmSave()}};
 const rows=document.querySelectorAll('[data-qty]');rows.forEach(input=>{const i=state.cart.items[Number(input.dataset.qty)];input.closest('tr').querySelector('small').insertAdjacentHTML('beforeend',`<br>${PLACES[locationOf(i)]}`)});
 $('#cart-client').insertAdjacentHTML('afterend',`<p class="note">Tabela: ${esc(priceTable(clientById(state.cart.client))||'A definir pelo gestor')}. Trocar o cliente recalcula os itens deste rascunho.</p>`);
};
const oldCatalog=catalog;
catalog=function(){oldCatalog();if(!$('#crm-client-select')){const html=`<section class="panel panel-body client-context"><label>Cliente do pedido<select class="wide" id="crm-client-select"><option value="">Selecione um cliente</option>${visibleClients().map(c=>`<option value="${c.id}" ${c.id===state.cart.client?'selected':''}>${esc(c.name)} · ${esc(c.establishment||'Oficina')}</option>`).join('')}</select></label><p class="note">Tabela: ${esc(priceTable(clientById(state.cart.client))||'A definir pelo gestor')} · preços fictícios por perfil.</p><button onclick="shareCatalog()">Compartilhar catálogo do site</button></section>`;$('#view .toolbar').insertAdjacentHTML('beforebegin',html);$('#crm-client-select').onchange=e=>{state.cart.client=e.target.value;repriceCart();save();$('#view').innerHTML='';catalog()}}
};
function shareCatalog(){modal('Catálogo central Motorflu',`<p>O cliente recebe o catálogo público do site. Os preços e as condições comerciais deste aplicativo não são compartilhados por esse link.</p><p><a href="https://motorflu.com.br/" target="_blank" rel="noopener">Abrir catálogo no site Motorflu</a></p><label>Link para compartilhar<input readonly value="https://motorflu.com.br/" id="catalog-url"></label><a class="button primary wide" href="https://wa.me/?text=${encodeURIComponent('Conheça o catálogo Motorflu: https://motorflu.com.br/')}" target="_blank" rel="noopener">Abrir WhatsApp para compartilhar</a><p class="note">Você escolhe o destinatário e confirma o envio no WhatsApp.</p>`)}
function clientForm(id,afterSave){
 const c=state.clients.find(c=>c.id===id&&(role==='gestor'||c.rep===user))||{};if(id&&!c.id)return;
 const fields=[['name','Nome fantasia',true],['legal','Razão social',true],['cnpj','CNPJ',true],['contact','Responsável',true],['phone','WhatsApp / Telefone',true],['email','E-mail',false],['city','Cidade / UF',true],['address','Endereço completo',true],['zip','CEP',false]];
 modal(id?'Editar cliente':'Novo cliente',`<form id="client-form"><div class="formgrid">${fields.map(([n,l,r])=>`<label>${l}${r?' *':''}<input name="${n}" ${r?'required':''} ${n==='email'?'type="email"':''} value="${esc(c[n]||'')}"></label>`).join('')}<label>Tipo de estabelecimento<select name="establishment" class="wide" id="client-type">${[...TABLES,'Outros'].map(x=>`<option ${x===(c.establishment||'Oficina')?'selected':''}>${x}</option>`).join('')}</select></label>${role==='gestor'?`<label>Tabela para Outros<select name="priceTable" class="wide"><option value="">Definir depois</option>${TABLES.map(x=>`<option ${x===c.priceTable?'selected':''}>${x}</option>`).join('')}</select></label><label>Representante<select name="rep" class="wide">${state.reps.filter(r=>r.active).map(r=>`<option ${c.rep===fullName(r)?'selected':''}>${esc(fullName(r))}</option>`).join('')}</select></label>`:'<p class="note">Para Outros, a tabela é definida pelo gestor antes da venda.</p>'}</div><button class="primary wide" style="margin-top:20px">Salvar cliente</button></form>`);
 $('#client-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(data))data[k]=data[k].trim();data.rep=role==='gestor'?data.rep:user;
  if(!['name','legal','contact','city','address'].every(k=>data[k])){toast('Preencha os dados obrigatórios.');return}if(!validPhone(data.phone)||!validCnpj(data.cnpj)){toast('Informe CNPJ válido e telefone com DDD.');return}
  if(state.clients.some(x=>x.id!==id&&digits(x.cnpj)===digits(data.cnpj))){toast('Este CNPJ já está cadastrado. Use o cadastro existente ou consulte o gestor.');return}
  if(role!=='gestor')data.priceTable=c.priceTable||'';
  const row={...c,...data,id:c.id||uid(),code:c.code||nextCode('CLI',state.clients)};
  if(id)Object.assign(c,row);else state.clients.push(row);state.cart.client=row.id;repriceCart();if(!crmSave())return;$('#modal').close();render();toast('Cliente salvo.');afterSave?.(row);
 };
}
function editPrice(id){
 if(role!=='gestor')return;const p=product(id),vs=variants(p),o=state.offers[id]||{};
 modal('Gerenciar '+esc(p.name),`<form id="manage-form"><p class="note">Preços fictícios. Os pedidos aprovados mantêm os valores registrados.</p>${vs.map((v,n)=>`<fieldset><legend>${esc(v)}</legend><div class="formgrid">${TABLES.map((t,k)=>`<label>Preço ${t} (R$)<input name="price${n}_${k}" type="number" min="0.01" step="0.01" required value="${tableBase(p,v,t)}"></label>`).join('')}${Object.entries(PLACES).map(([loc,title])=>`<label>Estoque atual · ${title}<input name="stock${n}_${loc}" type="number" min="0" step="1" required value="${stock(id,v,loc)}"><small>Reservado ${reserved(id,v,loc)} · disponível ${available(id,v,loc)}</small></label>`).join('')}</div></fieldset>`).join('')}<label class="checkline"><input name="sampleAvailable" type="checkbox" ${sampleAllowed(id)?'checked':''}> Disponibilizar amostra</label><h3>Oferta / campanha</h3><label>Nome da oferta<input name="title" value="${esc(o.title||'')}"></label><label>Desconto (%)<input name="percent" type="number" min="0" max="100" step="0.01" value="${o.percent||0}" required></label><div class="formgrid"><label>Início<input name="start" type="date" value="${o.start||''}"></label><label>Fim<input name="end" type="date" value="${o.end||''}"></label></div><p class="note">Zero desativa a oferta. Não há bônus para representantes nesta etapa. Zerar estoque é permitido; falta de estoque impede a aprovação das reservas.</p><label>Observação sobre o ajuste de estoque<input name="stockNote" placeholder="Ex.: contagem física / entrada de mercadoria"></label><button class="primary wide" style="margin-top:20px">Salvar alterações</button></form>`);
 mountProductPhoto(id);$('#manage-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.start&&d.end&&d.end<d.start){toast('Confira o período da oferta.');return}
 for(let n=0;n<vs.length;n++){const v=vs[n];TABLES.forEach((t,k)=>crm.tables[`${t}::${sku(id,v)}`]=Number(d[`price${n}_${k}`]));state.variantPrices[sku(id,v)]=Number(d[`price${n}_0`]);for(const loc of ['A','B']){const before=stock(id,v,loc),value=Number(d[`stock${n}_${loc}`]);crm.locationStock[placeKey(id,v,loc)]=value;if(value!==before)logStock('Ajuste manual',[{id,pack:v,location:loc,before,after:value,qty:value-before}],d.stockNote)}}
 state.sampleSettings[id]=d.sampleAvailable==='on';state.offers[id]={title:d.title,percent:Number(d.percent),start:d.start,end:d.end};if(!crmSave())return;$('#modal').close();render();toast('Catálogo e estoque atualizados.');
 };
}
function inventory(){
 $('#view').innerHTML=heading('Disponibilidade por local','Estoque disponível.','O pedido enviado reserva o produto. A aprovação baixa o físico uma única vez.',role==='gestor'?`<button onclick="stockHistory()">Histórico de alterações</button>`:'')+`<div class="toolbar"><input id="stock-search" placeholder="Buscar produto" aria-label="Buscar produto"></div><div id="stock-list"></div>`;
 const draw=()=>{$('#stock-list').innerHTML=PRODUCTS.filter(p=>p.name.toLowerCase().includes($('#stock-search').value.toLowerCase())).map(p=>`<section class="panel panel-body crm-card"><h3>${esc(p.name)}</h3>${variants(p).map(v=>`<h4>${esc(v)}</h4><div class="crm-grid">${Object.entries(PLACES).map(([loc,label])=>`<div class="stock-place"><strong>${label}</strong><p>Disponível: <b>${available(p.id,v,loc)}</b></p><small>Físico ${stock(p.id,v,loc)} · reservado ${reserved(p.id,v,loc)}</small>${reserved(p.id,v,loc)>stock(p.id,v,loc)?'<p class="error-text">Físico abaixo das reservas. Regularize antes de aprovar.</p>':''}</div>`).join('')}</div>`).join('')}${role==='gestor'?`<button class="wide" onclick="editPrice('${p.id}')">Editar estoques e preços</button>`:''}</section>`).join('')};$('#stock-search').oninput=draw;draw();
}
function stockHistory(){if(role!=='gestor')return;modal('Histórico de estoque',crm.stockLog.slice().reverse().slice(0,100).map(l=>`<article class="crm-card"><strong>${esc(l.kind)}</strong><p>${esc(l.by)} · ${shortDate(l.date)}</p><p>${esc(l.note)}</p>${l.items.map(i=>`<p class="note">${esc(product(i.id)?.name||i.id)} · ${esc(i.pack)} · ${PLACES[locationOf(i)]} · ${i.before!==undefined?`${i.before} → ${i.after}`:`${i.qty} unidade(s)`}</p>`).join('')}</article>`).join('')||'<p>Nenhuma movimentação registrada.</p>')}
const crmTools=[['goalsPage','Metas do mês','Acompanhe vendas aprovadas e o progresso mensal.'],['visitsPage','Agenda de visitas','Programação, GPS e solicitações de reagendamento.'],['offersPage','Ofertas','Produtos com desconto e campanhas em destaque.'],['inventory','Estoque disponível','Consulte fábrica e galpão por embalagem.'],['contactPage','Fale com a gestão','Preços de mercado, fotos e comentários.'],['followupsPage','Recompra e contatos','Próximos contatos por cliente e produto.'],['sampleResults','Resultado das amostras','Acompanhe entrega e conversão em vendas.'],['expensesPage','Despesas','Comprovantes e totais por período.'],['consignmentPage','Consignação','Solicitações, aprovações e acertos de mercadoria.']];
for(const [key] of crmTools)navIcon[key]=navIcon.orders;
navIcon.commercialHub=navIcon.dashboard;
function crmButtons(){return crmTools.map(([key,label,desc])=>`<button class="crm-tool" onclick="go('${key}')"><span class="action-icon">${navIcon[key]}</span><span><strong>${label}</strong><small>${desc}</small></span><span>→</span></button>`).join('')+`${role==='rep'?'<button class="crm-tool" onclick="calculator()"><span class="action-icon">＋</span><span><strong>Calculadora</strong><small>Contas simples sem sair do aplicativo.</small></span><span>→</span></button>':''}<button class="crm-tool" onclick="shareCatalog()"><span class="action-icon">↗</span><span><strong>Compartilhar catálogo</strong><small>Envie o link público pelo WhatsApp.</small></span><span>→</span></button>`}
function commercialHub(){$('#view').innerHTML=heading('Motorflu em movimento','Ferramentas comerciais.','Organize a rotina e acompanhe os resultados.')+`<div class="crm-tools">${crmButtons()}</div>${role==='gestor'?'<button class="wide" style="margin-top:24px" onclick="managersPage()">Gestores e locais de trabalho</button><button class="wide" style="margin-top:12px" onclick="pendingItems()">Pendências para implantação definitiva</button>':''}`}
const baseDashboard=dashboard;
dashboard=function(){baseDashboard();$('#view .stats').insertAdjacentHTML('afterend',`<section class="panel panel-body crm-card" id="goal-summary">${goalSummary(role==='gestor'?null:user,monthNow())}</section><section class="panel panel-body crm-card"><h2>Rotina comercial</h2><div class="crm-tools">${crmButtons()}</div></section>`)};
function approvedSales(rep,month){return state.orders.filter(o=>APPROVED.includes(o.status)&&(!rep||o.rep===rep)&&new Date(approvalDate(o)).toLocaleDateString('sv-SE').slice(0,7)===month).reduce((n,o)=>n+sum(o.items),0)}
function goalKey(rep,month){return `${rep}::${month}`}
function goalValue(rep,month){return rep?Number(crm.goals[goalKey(rep,month)]||0):state.reps.reduce((n,r)=>n+Number(crm.goals[goalKey(fullName(r),month)]||0),0)}
function goalSummary(rep,month){const target=goalValue(rep,month),sales=approvedSales(rep,month),percent=target?Math.round(sales/target*1000)/10:0;return `<div class="goal-layout"><div class="goal-dial" style="--progress:${Math.min(100,percent)}" role="img" aria-label="${target?percent+'% da meta atingida':'Meta ainda não definida'}"><span>${target?percent+'%':'—'}<small>da meta</small></span></div><div><span class="eyebrow">${esc(month.split('-').reverse().join('/'))} · ${rep?'Meu desempenho':'Equipe comercial'}</span><h2>${money(sales)} em vendas aprovadas</h2><p>Meta: <strong>${target?money(target):'A definir pelo gestor'}</strong></p><p>${target?`Faltam ${money(Math.max(0,target-sales))} para atingir a meta.`:'O gestor pode cadastrar a meta mensal por representante.'}</p><button onclick="go('goalsPage')">Ver metas</button></div></div>`}
function goalsPage(){
 $('#view').innerHTML=heading('Resultados comerciais','Metas mensais.','Somente pedidos aprovados, em preparação ou concluídos entram no resultado. Cancelamentos saem do total.')+`<div class="toolbar"><label>Mês<input id="goals-month" type="month" value="${monthNow()}"></label></div><div id="goals-list"></div>`;
 const draw=()=>{const month=$('#goals-month').value;if(!month)return;const reps=state.reps.filter(r=>role==='gestor'||fullName(r)===user);$('#goals-list').innerHTML=reps.map(r=>`<section class="panel panel-body crm-card"><h3>${esc(fullName(r))} · ${esc(r.code)}</h3>${goalSummary(fullName(r),month)}${role==='gestor'?`<form class="goal-form" data-rep="${r.id}"><label>Meta de vendas (R$)<input name="target" type="number" min="0" step="0.01" required value="${goalValue(fullName(r),month)}"></label><button class="primary">Salvar meta</button></form>`:''}</section>`).join('');document.querySelectorAll('.goal-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();const r=state.reps.find(x=>x.id===f.dataset.rep);crm.goals[goalKey(fullName(r),month)]=Number(new FormData(f).get('target'));if(crmSave()){draw();toast('Meta mensal atualizada.')}})};$('#goals-month').onchange=draw;draw();
}
function calculator(){
 if(role!=='rep')return;modal('Calculadora',`<div class="calculator"><output id="calc-display" aria-live="polite">0</output><div class="calc-keys">${['C','⌫','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','±','0',',','='].map(x=>`<button type="button" data-calc="${x}" aria-label="${x==='⌫'?'Apagar último dígito':x}">${x}</button>`).join('')}</div></div>`);
 let display='0',stored=null,op=null,reset=false;
 const show=()=>$('#calc-display').textContent=display.replace('.',',');
 const compute=()=>{const b=Number(display),a=stored;if(op==='÷'&&b===0)throw Error('Divisão por zero');const v=op==='+'?a+b:op==='−'?a-b:op==='×'?a*b:op==='÷'?a/b:b;if(!Number.isFinite(v))throw Error('Resultado inválido');return String(Number(v.toPrecision(12)))};
 document.querySelectorAll('[data-calc]').forEach(b=>b.onclick=()=>{const key=b.dataset.calc;try{if(key==='C'){display='0';stored=null;op=null;reset=false}else if(key==='⌫'){display=display.length>1?display.slice(0,-1):'0';if(display==='-')display='0'}else if(key==='±'){display=String(-Number(display))}else if(key==='%'){display=String(Number(display)/100)}else if(['+','−','×','÷'].includes(key)){if(op&&!reset)display=compute();stored=Number(display);op=key;reset=true}else if(key==='='){if(op){display=compute();op=null;stored=null;reset=true}}else{if(reset){display='0';reset=false}if(key===','){if(!display.includes('.'))display+='.'}else if(display.replace('-','').length<14)display=display==='0'?key:display+key}show()}catch(e){display='0';stored=null;op=null;reset=true;$('#calc-display').textContent=e.message}});
}
function offersPage(){const list=PRODUCTS.filter(p=>offerActive(p));$('#view').innerHTML=heading('Campanhas comerciais','Ofertas em destaque.','Descontos vigentes sobre a tabela do cliente. Sem bônus para o vendedor.',role==='gestor'?`<button class="primary" onclick="go('catalog')">Gerenciar ofertas no catálogo</button>`:'')+`${list.length?`<div class="crm-offers">${list.map(p=>`<section class="panel panel-body crm-card"><img class="offer-photo" src="${photo(p.id)}" alt="${esc(p.name)}">${promotionLabel(p)}<h2>${esc(p.name)}</h2><p>${esc(offerActive(p).title||'Oferta Motorflu')}</p><strong>${money(variantPrice(p,variants(p)[0]))}</strong><p class="note">${esc(variants(p)[0])} · tabela ${esc(priceTable(clientById(state.cart.client))||'a definir')}${offerActive(p).end?' · até '+esc(offerActive(p).end.split('-').reverse().join('/')):''}</p><button class="primary wide" onclick="${role==='gestor'?`editPrice('${p.id}')`:`chooseItem('${p.id}')`}">${role==='gestor'?'Editar oferta':'Adicionar ao pedido'}</button></section>`).join('')}</div>`:'<section class="panel empty">Nenhuma oferta vigente. O gestor pode cadastrar descontos no catálogo.</section>'}`}
function clientOptions(selected='',required=true){return `<option value="">${required?'Selecione o cliente':'Todos os clientes'}</option>${visibleClients().map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${esc(c.name)} · ${esc(c.cnpj||c.code)}</option>`).join('')}`}
function repOptions(selected){return state.reps.filter(r=>r.active).map(r=>`<option value="${r.id}" ${selected===fullName(r)?'selected':''}>${esc(fullName(r))} · ${esc(r.code)}</option>`).join('')}
function visitStatus(v){return v.checkout?'Concluída':v.checkin?'Em visita':v.reschedule?'Reagendamento em análise':new Date(v.scheduled)<new Date()?'Prazo vencido':'Programada'}
function visitsPage(){
 const list=crm.visits.filter(mine).slice().sort((a,b)=>a.scheduled.localeCompare(b.scheduled));
 $('#view').innerHTML=heading('Agenda comercial','Visitas programadas.','Check-in e check-out registram horário e localização do aparelho.',`<button class="primary" onclick="visitForm()">＋ ${role==='gestor'?'Atribuir visita':'Programar visita'}</button>`)+`<div class="toolbar"><select id="visit-filter" aria-label="Filtrar visitas"><option value="open">Em aberto</option><option value="all">Todas</option><option value="done">Concluídas</option></select></div><div id="visit-list"></div>`;
 const draw=()=>{const filter=$('#visit-filter').value;const chosen=list.filter(v=>filter==='all'||(filter==='done'?v.checkout:!v.checkout));$('#visit-list').innerHTML=chosen.map(v=>`<section class="panel panel-body crm-card"><span class="tag">${visitStatus(v)}</span><h3>${esc(v.client.name)}</h3><p>${shortDate(v.scheduled)}<br>${esc(v.rep)}<br>Origem: ${v.assigned?'Gestor comercial':'Representante'}</p><p class="note">${esc(v.offer||'Sem oferta informada')}</p><button class="wide" onclick="visitDetail('${v.id}')">Abrir visita</button></section>`).join('')||'<section class="panel empty">Nenhuma visita neste filtro.</section>'};$('#visit-filter').onchange=draw;draw();
}
function visitForm(id){
 const v=crm.visits.find(v=>v.id===id&&mine(v));if(id&&!v)return;
 if(v&&(v.checkin||v.checkout)){toast('A visita já foi iniciada. Consulte o histórico.');return}
 if(v?.assigned&&role!=='gestor'){requestReschedule(v.id);return}
 modal(v?'Editar programação':role==='gestor'?'Atribuir visita':'Programar visita',`<form id="visit-form"><label>Cliente cadastrado<select name="client" class="wide" required id="visit-client">${clientOptions(v?.clientId)}</select></label><div id="visit-client-info" class="note"></div>${role==='gestor'?`<label>Representante responsável<select name="repId" class="wide">${repOptions(v?.rep)}</select></label>`:''}<label>Data e horário / prazo de execução<input type="datetime-local" name="scheduled" required value="${v?.scheduled||''}"></label><label>Oferta / produtos apresentados<input name="offer" value="${esc(v?.offer||'')}"></label><label>Observação<textarea name="notes">${esc(v?.notes||'')}</textarea></label><p class="note">O check-in e o check-out exigem permissão de localização. São registrados os pontos e a precisão informada pelo GPS, sem rastreamento contínuo.</p><button class="primary wide">Salvar programação</button></form>`);
 const show=()=>{const c=clientById($('#visit-client').value);$('#visit-client-info').textContent=c?`CNPJ ${c.cnpj} · ${c.contact} · ${c.phone}`:''};$('#visit-client').onchange=show;show();
 $('#visit-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),c=clientById(d.client);if(!c||!validCnpj(c.cnpj)){toast('Selecione um cliente com CNPJ válido.');return}const rep=role==='gestor'?fullName(state.reps.find(r=>r.id===d.repId)):user;if(!rep)return;
 const data={...v,id:v?.id||uid(),clientId:c.id,client:structuredClone(c),rep,scheduled:d.scheduled,offer:d.offer,notes:d.notes,assigned:v?.assigned||role==='gestor',createdBy:v?.createdBy||user,history:[...(v?.history||[]),{date:now(),by:user,note:v?'Programação atualizada':'Visita programada'}]};
 if(v)Object.assign(v,data);else crm.visits.push(data);if(!crmSave())return;$('#modal').close();go('visitsPage');toast('Visita salva na agenda.');
 };
}
function geoMarkup(point,label){return point?`<div class="geo-point"><strong>${label}: ${shortDate(point.date)}</strong><p class="note">Latitude ${point.lat.toFixed(6)} · longitude ${point.lng.toFixed(6)}<br>Precisão aproximada: ${Math.round(point.accuracy)} m</p><a class="button" href="https://www.google.com/maps?q=${point.lat},${point.lng}" target="_blank" rel="noopener">Ver ponto no mapa</a></div>`:`<p class="note">${label}: ainda não registrado.</p>`}
function visitDetail(id){const v=crm.visits.find(v=>v.id===id&&mine(v));if(!v)return;
 modal('Visita · '+esc(v.client.name),`<span class="tag">${visitStatus(v)}</span><p><strong>${shortDate(v.scheduled)}</strong><br>${esc(v.rep)}</p><p>CNPJ: ${esc(v.client.cnpj)}<br>Contato: ${esc(v.client.contact)} · ${esc(v.client.phone)}<br>${esc(v.client.address)} · ${esc(v.client.city)}</p><p><strong>Oferta:</strong> ${esc(v.offer||'Não informada')}</p><p>${esc(v.notes)}</p>${geoMarkup(v.checkin,'Check-in')}${geoMarkup(v.checkout,'Check-out')}${v.result?`<p><strong>Resultado:</strong> ${esc(v.result)}</p>`:''}<div id="gps-message" class="note" role="status"></div>${!v.checkout&&role==='rep'?`<button class="primary wide" id="visit-gps">${v.checkin?'Registrar check-out com GPS':'Registrar check-in com GPS'}</button>${v.checkin?'<label>Resultado / comentário da visita<textarea id="visit-result" placeholder="Produtos apresentados e próximos passos"></textarea></label>':''}`:''}${!v.checkin?`<button class="wide" style="margin-top:12px" onclick="visitForm('${id}')">${v.assigned&&role==='rep'?'Solicitar reagendamento':'Editar programação'}</button>`:''}${v.reschedule?`<section class="message-preview"><h3>Solicitação de reagendamento</h3><p>${shortDate(v.reschedule.scheduled)}<br>${esc(v.reschedule.reason)}</p>${role==='gestor'?`<button onclick="decideReschedule('${id}',true)">Aprovar nova data</button><button onclick="decideReschedule('${id}',false)">Recusar e manter data</button>`:''}</section>`:''}<h3>Histórico</h3>${(v.history||[]).map(h=>`<p class="note">${shortDate(h.date)} · ${esc(h.by)}<br>${esc(h.note)}</p>`).join('')}`);
 if($('#visit-gps'))$('#visit-gps').onclick=()=>visitGps(id);
}
function visitGps(id){
 const v=crm.visits.find(v=>v.id===id&&v.rep===user);if(!v||role!=='rep'||v.checkout)return;
 const msg=$('#gps-message'),b=$('#visit-gps');if(!navigator.geolocation){msg.textContent='GPS indisponível neste navegador. Abra no navegador do celular e tente novamente.';return}
 const result=$('#visit-result')?.value||'';b.disabled=true;msg.textContent='Obtendo localização. Autorize o acesso quando o celular solicitar.';
 navigator.geolocation.getCurrentPosition(pos=>{const point={date:now(),lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy};const type=v.checkin?'checkout':'checkin';v[type]=point;if(type==='checkout')v.result=result;v.history.push({date:point.date,by:user,note:type==='checkin'?'Check-in com GPS':'Check-out com GPS'});crmSave();visitsPage();visitDetail(id)},err=>{if($('#gps-message'))$('#gps-message').textContent=err.code===1?'Permissão de localização negada. Habilite o acesso nas configurações do navegador e tente novamente.':'Não foi possível obter a localização. Verifique o GPS/sinal e tente novamente.';if($('#visit-gps'))$('#visit-gps').disabled=false},{enableHighAccuracy:true,timeout:20000,maximumAge:0});
}
function requestReschedule(id){const v=crm.visits.find(v=>v.id===id&&v.rep===user);if(!v||v.checkin)return;modal('Solicitar reagendamento',`<form id="reschedule-form"><p>A data atual continua válida até a decisão do gestor.</p><label>Nova data e horário<input name="scheduled" type="datetime-local" required></label><label>Motivo<textarea name="reason" required></textarea></label><button class="primary wide">Enviar solicitação</button></form>`);$('#reschedule-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.reason.trim())return;v.reschedule={...d,reason:d.reason.trim(),date:now(),by:user};v.history.push({date:now(),by:user,note:'Solicitou reagendamento para '+shortDate(d.scheduled)});crmSave();visitsPage();visitDetail(id)}}
function decideReschedule(id,approved){if(role!=='gestor')return;const v=crm.visits.find(v=>v.id===id);if(!v?.reschedule)return;if(approved)v.scheduled=v.reschedule.scheduled;v.history.push({date:now(),by:user,note:(approved?'Aprovou':'Recusou')+' o reagendamento. '+v.reschedule.reason});delete v.reschedule;crmSave();visitsPage();visitDetail(id)}
function dateRangeControls(prefix){return `<div class="toolbar"><label>De<input type="date" id="${prefix}-from" value="${monthNow()}-01"></label><label>Até<input type="date" id="${prefix}-to" value="${today()}"></label>${role==='gestor'?`<label>Representante<select id="${prefix}-rep" class="wide"><option value="">Todos</option>${repOptions('')}</select></label>`:''}</div>`}
function rangeMatches(x,prefix){const start=$('#'+prefix+'-from').value,end=$('#'+prefix+'-to').value,id=$('#'+prefix+'-rep')?.value,rep=state.reps.find(r=>r.id===id);return mine(x)&&(!start||x.date.slice(0,10)>=start)&&(!end||x.date.slice(0,10)<=end)&&(!rep||x.rep===fullName(rep))}
function expensesPage(){
 $('#view').innerHTML=heading('Controle de despesas','Despesas do vendedor.','Registre os gastos com comprovante e consulte totais por período.',role==='rep'?`<button class="primary" onclick="expenseForm()">＋ Registrar despesa</button>`:'')+dateRangeControls('expense')+`<section class="panel panel-body crm-card"><div id="expense-total"></div></section><div id="expense-list"></div>`;
 const draw=()=>{const list=crm.expenses.filter(x=>rangeMatches(x,'expense')).reverse();$('#expense-total').innerHTML=`<span class="eyebrow">Total do período</span><h2>${money(list.reduce((n,e)=>n+e.value,0))}</h2><p>${list.length} registro(s). Reembolso/aprovação financeira não configurados.</p>`;$('#expense-list').innerHTML=list.map(e=>`<section class="panel panel-body crm-card"><div class="crm-row"><h3>${esc(e.item)}</h3><strong>${money(e.value)}</strong></div><p>${esc(e.category)} · ${esc(e.date.split('-').reverse().join('/'))}<br>${esc(e.rep)}</p><p class="note">${esc(e.notes)}</p><button class="wide" onclick="expenseDetail('${e.id}')">Ver comprovante</button></section>`).join('')||'<section class="panel empty">Nenhuma despesa neste período.</section>'};for(const id of ['expense-from','expense-to','expense-rep'])if($('#'+id))$('#'+id).onchange=draw;draw();
}
function expenseForm(){if(role!=='rep')return;let attachment='';modal('Registrar despesa',`<form id="expense-form"><label>Item / descrição<input name="item" required placeholder="Ex.: almoço com cliente"></label><div class="formgrid"><label>Valor (R$)<input name="value" type="number" min="0.01" step="0.01" required></label><label>Data<input name="date" type="date" required value="${today()}"></label><label>Categoria<select class="wide" name="category">${['Alimentação','Estacionamento / zona azul','Combustível','Pedágio','Hospedagem','Outros'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><label>Observação<textarea name="notes" placeholder="Cliente, motivo ou detalhes"></textarea></label><h3>Foto do comprovante *</h3>${imagePicker('expense-photo','assets/icon-192.png')}<button class="primary wide">Salvar despesa</button></form>`);wireImagePicker('expense-photo',v=>attachment=v);$('#expense-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.item.trim()||!attachment||!(Number(d.value)>0)){toast('Informe descrição, valor e foto do comprovante.');return}crm.expenses.push({...d,item:d.item.trim(),value:Number(d.value),id:uid(),rep:user,photo:attachment,createdAt:now()});if(!crmSave()){crm.expenses.pop();return}$('#modal').close();go('expensesPage');toast('Despesa registrada com comprovante.')}}
function expenseDetail(id){const e=crm.expenses.find(x=>x.id===id&&mine(x));if(!e)return;modal('Comprovante de despesa',`<h3>${esc(e.item)} · ${money(e.value)}</h3><p>${esc(e.rep)} · ${esc(e.date)}<br>${esc(e.category)}</p><p>${esc(e.notes)}</p><img class="receipt-photo" src="${e.photo}" alt="Comprovante da despesa">`)}
function contactPage(){const list=crm.threads.filter(mine).slice().reverse();$('#view').innerHTML=heading('Relacionamento com a gestão',role==='gestor'?'Conversas comerciais.':'Fale com a gestão.','Registre produtos e preços encontrados no mercado, anexe fotos e acompanhe os comentários.',role==='rep'?`<button class="primary" onclick="newThread()">＋ Novo registro</button>`:'')+list.map(t=>`<section class="panel panel-body crm-card"><span class="eyebrow">${t.closed?'Conversa encerrada':'Em acompanhamento'}</span><h3>${esc(t.brand)} · ${esc(t.model)}</h3><p>${esc(t.volume)} · ${money(t.marketValue)}<br>${esc(t.rep)} · ${shortDate(t.date)}</p><p class="note">${esc(t.clientName||'Cliente não vinculado')} · ${t.messages.length} comentário(s)</p><button class="wide" onclick="threadDetail('${t.id}')">Abrir conversa</button></section>`).join('')+(!list.length?'<section class="panel empty">Nenhuma conversa registrada.</section>':'')}
function newThread(){if(role!=='rep')return;let attachment='';modal('Preço encontrado no mercado',`<form id="market-form"><label>Cliente / estabelecimento (opcional)<select name="clientId" class="wide">${clientOptions('',false)}</select></label><div class="formgrid"><label>Marca<input name="brand" required></label><label>Modelo / nome do produto<input name="model" required></label><label>Volume / embalagem<input name="volume" required placeholder="Ex.: 1 L"></label><label>Valor encontrado (R$)<input name="marketValue" type="number" min="0.01" step="0.01" required></label></div><label>Mensagem / observação<textarea name="notes" required></textarea></label><h3>Foto do produto ou da prateleira (opcional)</h3>${imagePicker('market-photo','assets/icon-192.png')}<button class="primary wide">Enviar à gestão</button><p class="note">A conversa é registrada nesta demonstração local. Não há notificação externa nem sincronização entre aparelhos.</p></form>`);wireImagePicker('market-photo',v=>attachment=v);$('#market-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.notes.trim())return;const c=clientById(d.clientId),t={id:uid(),brand:d.brand,model:d.model,volume:d.volume,marketValue:Number(d.marketValue),clientId:c?.id,clientName:c?.name,rep:user,date:now(),messages:[{id:uid(),by:user,role,date:now(),text:d.notes.trim(),photo:attachment}]};crm.threads.push(t);if(!crmSave()){crm.threads.pop();return}contactPage();threadDetail(t.id)}}
function threadDetail(id){const t=crm.threads.find(x=>x.id===id&&mine(x));if(!t)return;modal('Conversa · '+esc(t.brand),`<h3>${esc(t.model)} · ${esc(t.volume)}</h3><p>Valor encontrado: <strong>${money(t.marketValue)}</strong><br>${esc(t.clientName||'Cliente não vinculado')}</p><div class="thread-messages">${t.messages.map(m=>`<article class="thread-message ${m.role==='gestor'?'from-manager':''}"><strong>${esc(m.by)} · ${m.role==='gestor'?'Gestor':'Representante'}</strong><small>${shortDate(m.date)}</small><p>${esc(m.text)}</p>${m.photo?`<img class="thread-photo" src="${m.photo}" alt="Foto anexada à conversa">`:''}</article>`).join('')}</div>${!t.closed?`<form id="reply-form"><label>Comentário<textarea name="text" required></textarea></label><button class="primary wide">Registrar comentário</button></form>`:'<p>Conversa encerrada pela gestão.</p>'}${role==='gestor'?`<button class="wide" style="margin-top:12px" id="close-thread">${t.closed?'Reabrir conversa':'Encerrar conversa'}</button>`:''}`);if($('#reply-form'))$('#reply-form').onsubmit=e=>{e.preventDefault();const text=String(new FormData(e.target).get('text')).trim();if(!text)return;t.messages.push({id:uid(),text,by:user,role,date:now()});if(!crmSave()){t.messages.pop();return}contactPage();threadDetail(id)};if($('#close-thread'))$('#close-thread').onclick=()=>{t.closed=!t.closed;crmSave();contactPage();threadDetail(id)}}
function followupsPage(){const list=crm.followups.filter(mine).slice().sort((a,b)=>a.next.localeCompare(b.next));$('#view').innerHTML=heading('Relacionamento e recompra','Próximos contatos.','O representante define a próxima data por cliente/produto. Contatos vencidos aparecem como oportunidades.',`<button class="primary" onclick="followupForm()">＋ Agendar contato / consumo</button>`)+`<div class="toolbar"><select id="follow-filter" aria-label="Filtrar contatos"><option value="due">Oportunidades de hoje e atrasadas</option><option value="open">Todos em aberto</option><option value="all">Histórico completo</option></select></div><div id="follow-list"></div>`;const draw=()=>{const f=$('#follow-filter').value,rows=list.filter(x=>f==='all'||(!x.done&&(f!=='due'||x.next<=today())));$('#follow-list').innerHTML=rows.map(x=>`<section class="panel panel-body crm-card"><span class="tag">${x.done?'Contato realizado':x.next<=today()?'Oportunidade de recompra':'Contato programado'}</span><h3>${esc(clientById(x.clientId)?.name||x.clientName)}</h3><p>${esc(product(x.productId)?.name||'Contato geral')}<br>Próximo contato: ${esc(x.next.split('-').reverse().join('/'))}<br>${esc(x.rep)}</p>${x.consumption?`<p class="note">Consumo informado: ${esc(x.consumption)}</p>`:''}<p>${esc(x.notes)}</p>${!x.done?`<button class="wide" onclick="completeFollowup('${x.id}')">Registrar contato e próximo passo</button>`:`<p class="note">${shortDate(x.completedAt)} · ${esc(x.result)}</p>`}</section>`).join('')||'<section class="panel empty">Nenhum contato neste filtro.</section>'};$('#follow-filter').onchange=draw;draw()}
function followupForm(){modal('Programar próximo contato',`<form id="follow-form"><label>Cliente<select name="clientId" class="wide" required>${clientOptions()}</select></label>${role==='gestor'?`<label>Representante<select name="repId" class="wide">${repOptions('')}</select></label>`:''}<label>Produto / item<select name="productId" class="wide"><option value="">Contato geral</option>${PRODUCTS.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Consumo informado (opcional)<input name="consumption" placeholder="Ex.: 5 galões a cada 30 dias"></label><label>Próxima data de contato<input name="next" type="date" required></label><label>Observação<textarea name="notes"></textarea></label><button class="primary wide">Agendar contato</button></form>`);$('#follow-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),c=clientById(d.clientId);if(!c)return;crm.followups.push({...d,id:uid(),clientName:c.name,rep:role==='gestor'?fullName(state.reps.find(r=>r.id===d.repId)):user,date:now()});crmSave();$('#modal').close();go('followupsPage')}}
function completeFollowup(id){const x=crm.followups.find(x=>x.id===id&&mine(x));if(!x||x.done)return;modal('Resultado do contato',`<form id="follow-result"><label>Resultado / comentário<textarea name="result" required></textarea></label><label>Nova data de contato (opcional)<input name="next" type="date"></label><button class="primary wide">Salvar acompanhamento</button></form>`);$('#follow-result').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.result.trim())return;x.done=true;x.result=d.result.trim();x.completedAt=now();if(d.next)crm.followups.push({...x,id:uid(),done:false,result:'',completedAt:null,next:d.next,date:now(),notes:'Continuação: '+d.result.trim()});crmSave();$('#modal').close();followupsPage()}}
function sampleConversion(s){if(!s.deliveredAt||!APPROVED.includes(s.status))return null;const cnpj=digits(s.client.cnpj);return state.orders.find(o=>APPROVED.includes(o.status)&&digits(o.client.cnpj)===cnpj&&new Date(approvalDate(o))>=new Date(s.deliveredAt))||null}
function sampleResults(){const ss=state.samples.filter(mine),group=role==='gestor'?state.reps.map(fullName):[user];$('#view').innerHTML=heading('Amostras e resultados','Conversão em vendas.','Qualquer compra aprovada do mesmo CNPJ, após o registro de entrega da amostra, conta como conversão. Sem bônus.')+group.map(rep=>{const list=ss.filter(s=>s.rep===rep),delivered=list.filter(s=>s.deliveredAt&&APPROVED.includes(s.status)),converted=delivered.filter(sampleConversion);return `<section class="panel panel-body crm-card"><h3>${esc(rep)}</h3><div class="crm-metrics"><div><strong>${delivered.length}</strong><small>Entregues</small></div><div><strong>${converted.length}</strong><small>Convertidas</small></div><div><strong>${delivered.length-converted.length}</strong><small>Sem conversão até agora</small></div></div>${list.map(s=>{const order=sampleConversion(s);return `<article class="sample-result"><strong>#${esc(s.number)} · ${esc(s.client.name)}</strong><p class="note">${order?'Convertida pelo pedido #'+esc(order.number):s.deliveredAt?'Entregue · ainda sem conversão':APPROVED.includes(s.status)?'Aprovada · entrega não registrada':statusName(s.status)}${s.expectedShip?' · previsão de envio '+esc(s.expectedShip.split('-').reverse().join('/')):''}</p><button onclick="sampleDetail('${s.id}')">Ver amostra</button></article>`}).join('')||'<p class="note">Nenhuma amostra.</p>'}</section>`}).join('')}
function sampleDetail(id){const s=state.samples.find(s=>s.id===id&&mine(s));if(!s)return;const conversion=sampleConversion(s);modal('Amostra #'+esc(s.number),`${status(s.status)}<h3>${esc(s.client.name)}</h3><p>${esc(s.client.cnpj)}<br>${esc(s.client.contact)} · ${esc(s.client.phone)}<br>${esc(s.client.address)} · ${esc(s.client.city)}<br>Representante: ${esc(s.rep)}</p>${s.items.map(i=>`<div class="pick-product"><img src="${photo(i.id)}" alt="${esc(i.name)}"><div><strong>${esc(i.name)}</strong><p>${esc(i.pack)} · ${i.qty} unidade(s)<br>${PLACES[locationOf(i)]}</p></div></div>`).join('')}<p>${esc(s.notes)}</p><p>Previsão de envio: <strong>${s.expectedShip?esc(s.expectedShip.split('-').reverse().join('/')):'Não informada'}</strong></p><p>Entrega: ${s.deliveredAt?shortDate(s.deliveredAt):'Não registrada'}</p>${conversion?`<p class="promotion">Convertida em venda · pedido #${esc(conversion.number)}</p>`:''}<p class="manager-observation">${esc(s.managerNote||'')}</p>${role==='gestor'?`<form id="sample-manager"><label>Decisão<select name="decision" class="wide">${['Aguardando aprovação','Confirmado','Não aprovado'].map(x=>`<option value="${x}" ${s.status===x?'selected':''}>${x==='Confirmado'?'Liberada pela gestão':statusName(x)}</option>`).join('')}</select></label><label>Previsão de envio<input type="date" name="expectedShip" value="${s.expectedShip||''}"></label><label>Observação / motivo<textarea name="note">${esc(s.managerNote||'')}</textarea></label><button class="primary wide">Salvar liberação / previsão</button></form>${APPROVED.includes(s.status)&&!s.deliveredAt?'<button class="wide" id="sample-delivered" style="margin-top:12px">Registrar amostra entregue agora</button>':''}`:''}<h3>Histórico</h3>${(s.history||[]).map(h=>`<p class="note">${shortDate(h.date)} · ${esc(h.by)} · ${esc(statusName(h.status))}<br>${esc(h.note||'')}</p>`).join('')}<p class="note">Aviso disponível neste aplicativo local. E-mail para a fábrica aguarda configuração e não foi enviado.</p>`);
 if($('#sample-manager'))$('#sample-manager').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(s.deliveredAt&&d.decision!==s.status){toast('Amostra entregue mantém o histórico de liberação. Ajustes de devolução devem ser registrados no estoque.');return}if(!transitionOrder(s,d.decision,d.note.trim()))return;s.expectedShip=d.expectedShip;s.managerNote=d.note.trim();if(crmSave()){samples();sampleDetail(id);toast('Liberação e previsão registradas. E-mail não enviado.')}};
 if($('#sample-delivered'))$('#sample-delivered').onclick=()=>{s.deliveredAt=now();s.history.push({date:now(),by:user,status:'Entregue',note:'Entrega registrada para acompanhamento da conversão.'});crmSave();sampleDetail(id)};
}
function consignRemaining(c,n){const i=c.items[n];return i.qty-(i.sold||0)-(i.returned||0)}
function consignmentPage(){const list=crm.consignments.filter(mine).slice().reverse();$('#view').innerHTML=heading('Mercadoria em acompanhamento','Consignações.','Solicitações reservam estoque e dependem de aprovação. Acertos também são conferidos pela gestão.',`<button class="primary" onclick="consignmentForm()">＋ Solicitar consignação</button>`)+list.map(c=>`<section class="panel panel-body crm-card"><span class="tag">${c.closed?'Encerrada':APPROVED.includes(c.status)?'Em consignação':statusName(c.status)}</span><h3>#${esc(c.number)} · ${esc(c.client.name)}</h3><p>${esc(c.rep)}<br>Prazo de acerto: ${esc(c.deadline.split('-').reverse().join('/'))}</p><p>${c.items.reduce((n,i)=>n+i.qty,0)} unidade(s) deixadas · ${c.items.reduce((n,i,k)=>n+consignRemaining(c,k),0)} pendente(s)</p>${c.pendingSettlement?'<p class="promotion">Acerto aguardando aprovação da gestão</p>':''}<button class="wide" onclick="consignmentDetail('${c.id}')">Abrir consignação</button></section>`).join('')+(!list.length?'<section class="panel empty">Nenhuma consignação registrada.</section>':'')}
function consignmentForm(){
 const draft=[];modal('Solicitar consignação',`<form id="consign-form"><label>Cliente cadastrado<select class="wide" name="client" id="consign-client" required>${clientOptions()}</select></label><label>Prazo para acerto<input name="deadline" type="date" required min="${today()}"></label><fieldset><legend>Adicionar mercadoria</legend><label>Produto<select id="consign-product" class="wide">${PRODUCTS.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><div class="formgrid"><label>Embalagem<select id="consign-pack" class="wide"></select></label><label>Local<select id="consign-location" class="wide">${Object.entries(PLACES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Quantidade<input id="consign-qty" type="number" min="1" step="1" value="1"></label></div><p id="consign-stock" class="note"></p><button type="button" id="consign-add" class="wide">Adicionar item</button></fieldset><div id="consign-items"></div><label>Observação<textarea name="notes"></textarea></label><p class="note">Os preços ficam registrados na solicitação. Não gera venda até o gestor aprovar um acerto de itens vendidos.</p><button class="primary wide" style="margin-top:20px">Enviar para aprovação</button></form>`);
 const sync=()=>{const p=product($('#consign-product').value);$('#consign-pack').innerHTML=variants(p).map(v=>`<option>${esc(v)}</option>`).join('');stockInfo()};const stockInfo=()=>{$('#consign-stock').textContent=`Disponível: ${available($('#consign-product').value,$('#consign-pack').value,$('#consign-location').value)} unidades no local selecionado.`};$('#consign-product').onchange=sync;$('#consign-pack').onchange=stockInfo;$('#consign-location').onchange=stockInfo;
 const draw=()=>{$('#consign-items').innerHTML=draft.map((i,n)=>`<div class="sample-result"><strong>${esc(i.name)}</strong><p>${esc(i.pack)} · ${PLACES[i.location]} · ${i.qty} unidade(s) · ${money(i.price)} / un.</p><button type="button" data-remove-consign="${n}">Remover</button></div>`).join('');document.querySelectorAll('[data-remove-consign]').forEach(b=>b.onclick=()=>{draft.splice(Number(b.dataset.removeConsign),1);draw()})};
 $('#consign-add').onclick=()=>{const c=clientById($('#consign-client').value);if(!c||!priceTable(c)){toast('Selecione um cliente com tabela definida.');return}const p=product($('#consign-product').value),pack=$('#consign-pack').value,location=$('#consign-location').value,qty=Number($('#consign-qty').value);const i={id:p.id,name:p.name,pack,variant:pack,location,qty,price:Math.round(tableBase(p,pack,priceTable(c))*(1-(offerActive(p)?.percent||0)/100)*100)/100};if(!checkItems([...draft,i]))return;const existing=draft.find(x=>x.id===i.id&&x.pack===i.pack&&x.location===i.location);if(existing)existing.qty+=qty;else draft.push(i);draw()};
 $('#consign-client').onchange=()=>{if(draft.length){draft.length=0;draw();toast('Cliente alterado. Adicione os itens com a tabela correta.')}};
 $('#consign-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),client=clientById(d.client);if(!client||!completeClient(client)||!priceTable(client)){toast('Complete o cadastro e a tabela do cliente.');return}if(!draft.length||!checkItems(draft)){if(!draft.length)toast('Adicione pelo menos um produto.');return}const c={id:uid(),number:'C'+String(crm.consignments.length+1).padStart(5,'0'),client:structuredClone(client),rep:role==='gestor'?client.rep:user,date:now(),deadline:d.deadline,notes:d.notes,items:structuredClone(draft),status:'Aguardando aprovação',history:[{date:now(),by:user,status:'Solicitada'}]};crm.consignments.push(c);logStock('Reserva de consignação',c.items,'Consignação #'+c.number);if(!crmSave()){crm.consignments.pop();return}$('#modal').close();go('consignmentPage');toast('Consignação enviada para aprovação.')};sync();
}
function consignmentDetail(id){const c=crm.consignments.find(c=>c.id===id&&mine(c));if(!c)return;modal('Consignação #'+esc(c.number),`${status(c.status)}<h3>${esc(c.client.name)}</h3><p>CNPJ ${esc(c.client.cnpj)}<br>${esc(c.client.address)} · ${esc(c.client.city)}<br>${esc(c.client.phone)}<br>Representante: ${esc(c.rep)}</p><p>Prazo de acerto: <strong>${esc(c.deadline.split('-').reverse().join('/'))}</strong></p><p>${esc(c.notes)}</p><div class="tablewrap"><table><thead><tr><th>Produto / local</th><th>Deixado</th><th>Vendido</th><th>Devolvido</th><th>Restante</th></tr></thead><tbody>${c.items.map((i,n)=>`<tr><td>${esc(i.name)}<small>${esc(i.pack)} · ${PLACES[locationOf(i)]}</small></td><td>${i.qty}</td><td>${i.sold||0}</td><td>${i.returned||0}</td><td>${consignRemaining(c,n)}</td></tr>`).join('')}</tbody></table></div>${c.reason?`<p>Motivo: ${esc(c.reason)}</p>`:''}${c.status==='Aguardando aprovação'&&role==='gestor'?`<form id="consign-decision"><label>Observação / motivo<textarea name="note"></textarea></label><div class="modal-actions"><button type="submit" name="decision" value="reject">Não aprovar</button><button type="submit" class="primary" name="decision" value="approve">Aprovar consignação</button></div></form>`:''}${APPROVED.includes(c.status)&&!c.closed&&!c.pendingSettlement?`<button class="primary wide" style="margin-top:20px" onclick="settlementForm('${id}')">Registrar vendidos / devolvidos</button>`:''}${c.pendingSettlement?`<section class="message-preview"><h3>Acerto em análise</h3><p>${esc(c.pendingSettlement.by)} · ${shortDate(c.pendingSettlement.date)}</p>${c.pendingSettlement.items.map(x=>`<p>${esc(c.items[x.index].name)}: ${x.sold} vendido(s), ${x.returned} devolvido(s)</p>`).join('')}<p>${esc(c.pendingSettlement.notes)}</p>${role==='gestor'?`<button class="primary wide" onclick="approveSettlement('${id}')">Aprovar acerto</button><button class="wide" style="margin-top:8px" onclick="rejectSettlement('${id}')">Recusar acerto com motivo</button>`:''}</section>`:''}<h3>Histórico</h3>${c.history.map(h=>`<p class="note">${shortDate(h.date)} · ${esc(h.by)}<br>${esc(h.status)} ${esc(h.note||'')}</p>`).join('')}<p class="note">Envio de WhatsApp/e-mail para a fábrica ainda não configurado. Esta solicitação fica registrada no aplicativo local.</p>`);
 if($('#consign-decision'))$('#consign-decision').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),approve=e.submitter?.value==='approve';if(!approve&&!d.note.trim()){toast('Informe o motivo da não aprovação.');return}if(approve&&!takeStock(c.items,true))return;c.status=approve?'Confirmado':'Não aprovado';c.stockApplied=approve;c.approvedAt=approve?now():null;c.reason=d.note;c.history.push({date:now(),by:user,status:approve?'Liberada pela gestão':'Não aprovada',note:d.note});if(!approve)logStock('Liberação de reserva',c.items,'Consignação #'+c.number);crmSave();consignmentPage();consignmentDetail(id)};
}
function settlementForm(id){const c=crm.consignments.find(c=>c.id===id&&mine(c));if(!c||!APPROVED.includes(c.status)||c.closed||c.pendingSettlement)return;modal('Acerto de consignação',`<form id="settlement-form">${c.items.map((i,n)=>`<fieldset><legend>${esc(i.name)} · ${esc(i.pack)} · ${locationOf(i)}</legend><p>Saldo pendente: ${consignRemaining(c,n)} unidade(s).</p><div class="formgrid"><label>Quantidade vendida agora<input name="sold${n}" type="number" min="0" max="${consignRemaining(c,n)}" step="1" required value="0"></label><label>Quantidade devolvida agora<input name="returned${n}" type="number" min="0" max="${consignRemaining(c,n)}" step="1" required value="0"></label></div></fieldset>`).join('')}<label>Observação<textarea name="notes"></textarea></label><p class="note">O saldo restante é calculado automaticamente. A gestão aprova o acerto antes de registrar a venda e a devolução ao estoque.</p><button class="primary wide">Enviar acerto para aprovação</button></form>`);$('#settlement-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),items=c.items.map((i,n)=>({index:n,sold:Number(d['sold'+n]),returned:Number(d['returned'+n])}));if(!validSettlement(c,items)){toast('As quantidades vendidas e devolvidas não podem ultrapassar o saldo.');return}if(!items.some(i=>i.sold+i.returned>0)){toast('Informe uma venda ou devolução.');return}c.pendingSettlement={items,notes:d.notes,by:user,date:now()};c.history.push({date:now(),by:user,status:'Acerto solicitado'});crmSave();consignmentPage();consignmentDetail(id)}}
function validSettlement(c,items){return items.length===c.items.length&&new Set(items.map(x=>x.index)).size===items.length&&items.every(x=>c.items[x.index]&&Number.isInteger(x.sold)&&Number.isInteger(x.returned)&&x.sold>=0&&x.returned>=0&&x.sold+x.returned<=consignRemaining(c,x.index))}
function applySettlement(c){
 if(role!=='gestor'||!c.pendingSettlement||!validSettlement(c,c.pendingSettlement.items))return false;
 const settlement=c.pendingSettlement,sold=[];
 for(const row of settlement.items){const item=c.items[row.index];if(row.sold)sold.push({...structuredClone(item),qty:row.sold});if(row.returned)returnStock([{...item,qty:row.returned}],'Devolução consignação #'+c.number);item.sold=(item.sold||0)+row.sold;item.returned=(item.returned||0)+row.returned}
 if(sold.length){const date=now(),o={id:uid(),number:String(state.orders.length+1).padStart(6,'0'),date,approvedAt:date,rep:c.rep,repCode:repByName(c.rep)?.code,client:structuredClone(c.client),items:sold,payment:'Acerto de consignação',commercial:structuredClone(state.policy),notes:'Venda do acerto da consignação #'+c.number,status:'Confirmado',stockApplied:true,stockExempt:true,consignmentId:c.id,history:[{date,by:user,status:'Confirmado',note:'Acerto aprovado. Mercadoria já baixada na liberação da consignação.'}]};state.orders.push(o);c.history.push({date,by:user,status:'Acerto aprovado',note:'Venda registrada no pedido #'+o.number})}else c.history.push({date:now(),by:user,status:'Devolução aprovada'});
 c.settlements ||= [];c.settlements.push({...settlement,approvedBy:user,approvedAt:now()});delete c.pendingSettlement;c.closed=c.items.every((i,n)=>consignRemaining(c,n)===0);return true;
}
function approveSettlement(id){const c=crm.consignments.find(c=>c.id===id);if(!c||!applySettlement(c)){toast('Acerto indisponível ou quantidades inválidas.');return}crmSave();consignmentPage();consignmentDetail(id);toast('Acerto aprovado. Venda e devoluções registradas sem baixa duplicada.')}
function rejectSettlement(id){if(role!=='gestor')return;const c=crm.consignments.find(c=>c.id===id);if(!c?.pendingSettlement)return;modal('Recusar acerto',`<form id="settlement-reject"><label>Motivo<textarea name="reason" required></textarea></label><button class="primary wide">Registrar recusa</button></form>`);$('#settlement-reject').onsubmit=e=>{e.preventDefault();const reason=String(new FormData(e.target).get('reason')).trim();if(!reason)return;c.history.push({date:now(),by:user,status:'Acerto recusado',note:reason});delete c.pendingSettlement;crmSave();consignmentPage();consignmentDetail(id)}}
function pendingItems(){if(role!=='gestor')return;modal('Pendências para implantação',`<ol class="pending-list"><li><strong>Frete:</strong> receber tabela CIF de SP, abrangência e condições; definir Melhor Envio, pesos e dimensões das embalagens e origens dos envios.</li><li><strong>Cosmos:</strong> identificar fornecedor/versão, obter planilha aceita e códigos de clientes/produtos; confirmar o momento de envio à fábrica.</li><li><strong>Destinatários:</strong> informar WhatsApp e e-mails da fábrica/gestão e confirmar quem recebe pedidos, amostras e consignações.</li><li><strong>Uso real pela equipe:</strong> configurar banco compartilhado, autenticação individual, permissões por gestor/local, armazenamento das fotos e envio automático de mensagens.</li><li><strong>Dados definitivos:</strong> receber as três tabelas de preços, estoque inicial por local e embalagem e metas mensais.</li></ol><p class="note">A demonstração mantém dados somente neste navegador. Nenhum e-mail, WhatsApp ou pedido é enviado ao Cosmos.</p>`)}
// Keep existing navigation and original client/order functions; add the commercial hub.
const baseDecorate=decorateShell;
decorateShell=function(){baseDecorate();const button=document.querySelector('[data-nav="commercialHub"]');if(button&&role==='gestor'){const n=crm.visits.filter(v=>v.reschedule).length+crm.consignments.filter(c=>c.status==='Aguardando aprovação'||c.pendingSettlement).length;if(n)button.insertAdjacentHTML('beforeend',`<span class="badge">${n}</span>`)}};
const baseDetail=enhanceOrderDetail;
enhanceOrderDetail=function(o){baseDetail(o);$('#modal .modal-body').insertAdjacentHTML('beforeend',`<section><h3>Origem da mercadoria</h3>${o.items.map(i=>`<p class="note">${esc(i.name)} · ${esc(itemPack(i))} · ${PLACES[locationOf(i)]}</p>`).join('')}${o.priceTable?`<p class="note">Tabela do pedido: ${esc(o.priceTable)}</p>`:''}${o.consignmentId?'<p class="note">Venda de consignação: a baixa física ocorreu na liberação da mercadoria.</p>':''}</section>`)};
crmSave();

function managersPage(){if(role!=='gestor')return;modal('Gestores e locais de trabalho',`<p class="note">Todos os gestores desta demonstração podem editar os estoques A e B. Contas locais, sem autenticação segura nem sincronização entre aparelhos.</p>${state.managers.map(m=>`<article class="sample-result"><strong>${esc(fullName(m))}</strong><p>${esc(m.code)} · ${esc(m.workplace||'Gestão comercial')}<br>Login: ${esc(m.login)}</p></article>`).join('')}<button class="primary wide" onclick="managerForm()">Cadastrar gestor de demonstração</button>`)}
function managerForm(){if(role!=='gestor')return;modal('Cadastrar gestor',`<form id="manager-form"><label>Nome<input name="name" required></label><label>Sobrenome<input name="surname" required></label><label>Local<select name="workplace" class="wide"><option>Gestão comercial</option><option>Fábrica</option><option>Galpão estratégico</option></select></label><label>Login<input name="login" required autocomplete="off"></label><label>Senha de demonstração<input name="password" type="password" required autocomplete="new-password"></label><p class="note">Use somente dados fictícios e senhas de teste.</p><button class="primary wide">Salvar gestor</button></form>`);$('#manager-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(d))d[k]=d[k].trim();if(!d.name||!d.surname||!d.login||!d.password)return;if(state.managers.some(m=>m.login.toLowerCase()===d.login.toLowerCase())){toast('Já existe gestor com esse login.');return}state.managers.push({...d,id:uid(),code:nextCode('GES',state.managers),photo:''});if(!crmSave()){state.managers.pop();return}managersPage();toast('Gestor de demonstração cadastrado.')}}

function renameCommercialRep(oldName,newName){if(!newName||oldName===newName)return;for(const kind of ['visits','expenses','threads','followups','consignments'])for(const x of crm[kind])if(x.rep===oldName)x.rep=newName;for(const key of Object.keys(crm.goals))if(key.startsWith(oldName+'::')){crm.goals[newName+key.slice(oldName.length)]=crm.goals[key];delete crm.goals[key]}crmSave()}
const originalRepForm=repForm;
repForm=function(id){const r=state.reps.find(r=>r.id===id),oldName=fullName(r);originalRepForm(id);const form=$('#team-form');if(!form)return;const submit=form.onsubmit;form.onsubmit=e=>{submit(e);if(r)renameCommercialRep(oldName,fullName(r))}};
const originalProfilePage=profilePage;
profilePage=function(){const p=currentProfile(),oldName=fullName(p);originalProfilePage();const form=$('#profile-form');if(!form)return;const submit=form.onsubmit;form.onsubmit=e=>{submit(e);if(role==='rep')renameCommercialRep(oldName,fullName(p))}};
